/**
 * Get signal analytics for a university.
 * Provides aggregate metrics for the analytics dashboard.
 */
export const getSignalAnalytics = query({
  args: {
    universityId: v.id('universities'),
    dateRange: v.optional(
      v.object({
        start: v.number(),
        end: v.number(),
      }),
    ),
  },
  handler: async (ctx, args) => {
    const sessionCtx = await getCurrentUser(ctx);

    // Authorization check
    if (sessionCtx.role !== 'super_admin') {
      const universityId = requireTenant(sessionCtx);
      if (universityId !== args.universityId) {
        throw new Error('Unauthorized: Cannot access analytics for another university');
      }
    }

    const now = Date.now();
    const thirtyDaysAgo = now - 30 * 24 * 60 * 60 * 1000;
    const start = args.dateRange?.start ?? thirtyDaysAgo;
    const end = args.dateRange?.end ?? now;

    // Get all signals for this university
    const allSignals = await ctx.db
      .query('signals')
      .withIndex('by_university', (q) => q.eq('university_id', args.universityId))
      .collect();

    // Filter by date range
    const signalsInRange = allSignals.filter((s) => s.created_at >= start && s.created_at <= end);

    // Current status breakdown
    const statusCounts = {
      active: allSignals.filter((s) => s.status === 'active').length,
      snoozed: allSignals.filter((s) => s.status === 'snoozed').length,
      resolved: allSignals.filter((s) => s.status === 'resolved').length,
      dismissed: allSignals.filter((s) => s.status === 'dismissed').length,
    };

    // Priority breakdown (active only)
    const activeSignals = allSignals.filter((s) => s.status === 'active');
    const priorityCounts = {
      urgent: activeSignals.filter((s) => s.priority === 'urgent').length,
      high: activeSignals.filter((s) => s.priority === 'high').length,
      medium: activeSignals.filter((s) => s.priority === 'medium').length,
      low: activeSignals.filter((s) => s.priority === 'low').length,
    };

    // Signal type breakdown (all signals in range)
    const typeCounts = {
      needs_outreach: signalsInRange.filter((s) => s.signal_type === 'needs_outreach').length,
      application_support: signalsInRange.filter((s) => s.signal_type === 'application_support')
        .length,
      document_review: signalsInRange.filter((s) => s.signal_type === 'document_review').length,
      milestone_check: signalsInRange.filter((s) => s.signal_type === 'milestone_check').length,
      custom: signalsInRange.filter((s) => s.signal_type === 'custom').length,
    };

    // Source breakdown
    const sourceCounts = {
      rule: signalsInRange.filter((s) => s.source === 'rule').length,
      manual: signalsInRange.filter((s) => s.source === 'manual').length,
      system: signalsInRange.filter((s) => s.source === 'system').length,
    };

    // Resolution type breakdown (resolved signals only)
    const resolvedSignals = signalsInRange.filter((s) => s.status === 'resolved');
    const resolutionCounts = {
      action_taken: resolvedSignals.filter((s) => s.resolution_type === 'action_taken').length,
      no_action_needed: resolvedSignals.filter((s) => s.resolution_type === 'no_action_needed')
        .length,
      dismissed: resolvedSignals.filter((s) => s.resolution_type === 'dismissed').length,
      auto_resolved: resolvedSignals.filter((s) => s.resolution_type === 'auto_resolved').length,
    };

    // Calculate average resolution time
    const resolvedWithTimes = resolvedSignals.filter((s) => s.resolved_at && s.triggered_at);
    let avgResolutionTimeHours: number | null = null;
    if (resolvedWithTimes.length > 0) {
      const totalMs = resolvedWithTimes.reduce(
        (sum, s) => sum + ((s.resolved_at || 0) - s.triggered_at),
        0,
      );
      avgResolutionTimeHours = Math.round(totalMs / resolvedWithTimes.length / (1000 * 60 * 60));
    }

    // Daily signal creation trend (last 30 days)
    const dailyTrend: { date: string; created: number; resolved: number }[] = [];
    for (let i = 29; i >= 0; i--) {
      const dayStart = now - (i + 1) * 24 * 60 * 60 * 1000;
      const dayEnd = now - i * 24 * 60 * 60 * 1000;
      const date = new Date(dayEnd).toISOString().split('T')[0];

      const created = allSignals.filter(
        (s) => s.created_at >= dayStart && s.created_at < dayEnd,
      ).length;
      const resolved = allSignals.filter(
        (s) =>
          s.status === 'resolved' &&
          s.resolved_at &&
          s.resolved_at >= dayStart &&
          s.resolved_at < dayEnd,
      ).length;

      dailyTrend.push({ date, created, resolved });
    }

    // Top students with most active signals
    const studentSignalCounts = new Map<string, number>();
    for (const s of activeSignals) {
      const count = studentSignalCounts.get(s.student_id) ?? 0;
      studentSignalCounts.set(s.student_id, count + 1);
    }
    const topStudentIds = Array.from(studentSignalCounts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10);

    const topStudents: Array<{
      studentId: string;
      name: string;
      email: string;
      activeSignals: number;
    }> = [];
    for (const [studentId, count] of topStudentIds) {
      const user = await ctx.db.get(studentId as Id<'users'>);
      if (user) {
        topStudents.push({
          studentId,
          name: user.name || 'Unknown',
          email: user.email || '',
          activeSignals: count,
        });
      }
    }

    // Top rules by signal count
    const ruleSignalCounts = new Map<string, number>();
    for (const s of signalsInRange) {
      if (s.rule_id) {
        const count = ruleSignalCounts.get(s.rule_id) ?? 0;
        ruleSignalCounts.set(s.rule_id, count + 1);
      }
    }
    const topRuleIds = Array.from(ruleSignalCounts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5);

    const topRules: Array<{
      ruleId: string;
      name: string;
      signalCount: number;
    }> = [];
    for (const [ruleId, count] of topRuleIds) {
      const rule = await ctx.db.get(ruleId as Id<'signal_rules'>);
      if (rule) {
        topRules.push({
          ruleId,
          name: rule.name,
          signalCount: count,
        });
      }
    }

    return {
      summary: {
        totalSignals: allSignals.length,
        activeSignals: statusCounts.active,
        signalsInPeriod: signalsInRange.length,
        resolvedInPeriod: resolvedSignals.length,
        avgResolutionTimeHours,
      },
      statusCounts,
      priorityCounts,
      typeCounts,
      sourceCounts,
      resolutionCounts,
      dailyTrend,
      topStudents,
      topRules,
    };
  },
});

/**
 * Get signal rule effectiveness metrics.
 * Shows how each rule is performing.
 */
export const getRuleEffectiveness = query({
  args: {
    universityId: v.id('universities'),
  },
  handler: async (ctx, args) => {
    const sessionCtx = await getCurrentUser(ctx);

    // Authorization check
    if (sessionCtx.role !== 'super_admin') {
      const universityId = requireTenant(sessionCtx);
      if (universityId !== args.universityId) {
        throw new Error('Unauthorized: Cannot access analytics for another university');
      }
    }

    // Get all rules for this university
    const rules = await ctx.db
      .query('signal_rules')
      .withIndex('by_university', (q) => q.eq('university_id', args.universityId))
      .collect();

    // Get all signals for this university
    const allSignals = await ctx.db
      .query('signals')
      .withIndex('by_university', (q) => q.eq('university_id', args.universityId))
      .collect();

    const ruleMetrics: Array<{
      ruleId: string;
      name: string;
      isActive: boolean;
      totalSignals: number;
      activeSignals: number;
      resolvedWithAction: number;
      resolvedNoAction: number;
      dismissedCount: number;
      avgResolutionHours: number | null;
      effectivenessRate: number;
    }> = [];

    for (const rule of rules) {
      const ruleSignals = allSignals.filter((s) => s.rule_id === rule._id);
      const activeCount = ruleSignals.filter((s) => s.status === 'active').length;
      const resolvedWithAction = ruleSignals.filter(
        (s) => s.status === 'resolved' && s.resolution_type === 'action_taken',
      ).length;
      const resolvedNoAction = ruleSignals.filter(
        (s) => s.status === 'resolved' && s.resolution_type === 'no_action_needed',
      ).length;
      const dismissedCount = ruleSignals.filter((s) => s.status === 'dismissed').length;

      const resolvedWithTimes = ruleSignals.filter(
        (s) => s.status === 'resolved' && s.resolved_at && s.triggered_at,
      );
      let avgResolutionHours: number | null = null;
      if (resolvedWithTimes.length > 0) {
        const totalMs = resolvedWithTimes.reduce(
          (sum, s) => sum + ((s.resolved_at || 0) - s.triggered_at),
          0,
        );
        avgResolutionHours = Math.round(totalMs / resolvedWithTimes.length / (1000 * 60 * 60));
      }

      // Effectiveness = action taken / (action taken + no action needed + dismissed)
      const totalResolved = resolvedWithAction + resolvedNoAction + dismissedCount;
      const effectivenessRate =
        totalResolved > 0 ? Math.round((resolvedWithAction / totalResolved) * 100) : 0;

      ruleMetrics.push({
        ruleId: rule._id,
        name: rule.name,
        isActive: rule.is_active,
        totalSignals: ruleSignals.length,
        activeSignals: activeCount,
        resolvedWithAction,
        resolvedNoAction,
        dismissedCount,
        avgResolutionHours,
        effectivenessRate,
      });
    }

    // Sort by total signals descending
    ruleMetrics.sort((a, b) => b.totalSignals - a.totalSignals);

    return ruleMetrics;
  },
});
